from fastapi import Path

@app.get('/items/{item_id}')
def get_item(item_id: int = Path(ge=1, le=100)):
    return {'item_id': item_id}
# /items/abc 与 /items/0 都返回 422

@app.get('/tasks')
def list_tasks(skip: int = 0, limit: int = 10, q: str | None = None):
    return {'skip': skip, 'limit': limit, 'q': q}

from pydantic import BaseModel

class Item(BaseModel):
    name: str
    price: float

@app.post('/items')
def create_item(item: Item):
    return item

from fastapi import Form, UploadFile, File

@app.post('/upload')
async def upload(file: UploadFile = File(...), note: str = Form('')):
    size = len(await file.read())
    return {'name': file.filename, 'size': size, 'note': note}

